CREATE UNIQUE INDEX IF NOT EXISTS uq_sources_name ON sources(name NULLS FIRST);

-- DD-CYN-0136 2-1: 用途を限定した鍵 (api_keys)。DD-CYN-0132 4-2 は SQLite 側 migrate_db にのみ
-- 追加しており、Postgres の空DB初期化経路 (本ファイル) に欠けていた。db.py の定義を Postgres 方言へ写す。
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', key_prefix TEXT NOT NULL DEFAULT '', key_hash TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'viewer', scope_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (TO_CHAR((CURRENT_TIMESTAMP AT TIME ZONE 'utc'), 'YYYY-MM-DD HH24:MI:SS')), created_by TEXT NOT NULL DEFAULT 'unknown', last_used_at TEXT, revoked_at TEXT);
CREATE INDEX IF NOT EXISTS idx_api_keys_hash ON api_keys(key_hash NULLS FIRST);

-- DD-CYN-0136 2-1: collections.egress_allowed (DD-CYN-0132 4-4)。既定 0 = 外へ出さない (fail-safe)。
